package org.light.challenge.core.agent.models

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable
import ai.koog.agents.core.tools.annotations.LLMDescription

/**
 * Rule model for LLM structured data generation.
 * Used to represent rules that should be generated by the LLM.
 */
@Serializable
@SerialName("LLMRule")
@LLMDescription("A workflow rule that defines conditions and actions for invoice processing")
data class LLMRule(
    @property:LLMDescription("Unique identifier for the rule (kebab-case format)")
    val id: String,
    
    @property:LLMDescription("Human-readable name for the rule")
    val name: String,
    
    @property:LLMDescription("Detailed description of what the rule does")
    val description: String,
    
    @property:LLMDescription("Priority level for rule evaluation (higher values = higher priority)")
    val priority: Int,
    
    @property:LLMDescription("Boolean expression that determines when the rule applies (e.g., 'invoice.amount > 10000 && invoice.department == \"marketing\"')")
    val conditionExpression: String,
    
    @property:LLMDescription("Action to execute when the rule condition is met")
    val action: LLMAction
) 